    front++;
    if (i < values.length && values[i] !== null) {
      parent.left = new TreeNode(values[i]);
      queue.push(parent.left);
    }
    i++;
    if (i < values.length && values[i] !== null) {
      parent.right = new TreeNode(values[i]);
      queue.push(parent.right);
    }
    i++;
  }
  return root;
}

// toArray(root) is the reverse: level order with nulls for gaps, trailing nulls removed.
function toArray(root) {
  const values = [];
  const queue = [root];
  let front = 0;
  while (front < queue.length) {
    const node = queue[front];
    front++;
    if (node === null) {
      values.push(null);
      continue;
    }
    values.push(node.val);
    queue.push(node.left, node.right);
  }
  while (values.length > 0 && values[values.length - 1] === null) values.pop();
  return values;
}
// ---- End of helpers ----

function maxDepth(root) {
  if (root === null) return 0;          // base case: an empty tree has no depth
  const leftDepth = maxDepth(root.left);   // trust the function on the smaller trees
  const rightDepth = maxDepth(root.right);
  return 1 + Math.max(leftDepth, rightDepth); // this node + the deeper side
}
